"""Stage published independent-trajectory evidence; standard library only.

This never imports numerical libraries, installs dependencies, or runs fits.
Use a fresh output directory and the git repository containing both frozen refs.
"""
from __future__ import annotations

import argparse
import hashlib
import io
import json
from pathlib import Path, PurePosixPath
import shlex
import shutil
import subprocess
import sys
import tarfile


def sha(value):
    return hashlib.sha256(value).hexdigest()


def canonical(value):
    return sha(json.dumps(value, sort_keys=True, allow_nan=False).encode())


def path_under(root, relative):
    parts = PurePosixPath(relative)
    if parts.is_absolute() or not parts.parts or any(p in ('..', '.') for p in parts.parts):
        raise ValueError(f'Unsafe path: {relative}')
    return root.joinpath(*parts.parts)


def manifest(root):
    return {
        p.relative_to(root).as_posix(): sha(p.read_bytes())
        for p in sorted(root.rglob('*'))
        if p.is_file() and '__pycache__' not in p.parts and p.suffix != '.pyc'
    }


def write_json(path, value):
    with path.open('x') as stream:
        json.dump(value, stream, indent=2, allow_nan=False)
        stream.write('\n')


def archive(repository, commit, destination):
    payload = subprocess.check_output(['git', 'archive', commit, 'src/resdag'], cwd=repository)
    with tarfile.open(fileobj=io.BytesIO(payload)) as stream:
        for entry in stream:
            target = path_under(destination, entry.name)
            if entry.isdir():
                target.mkdir(parents=True, exist_ok=True)
            elif entry.isfile():
                target.parent.mkdir(parents=True, exist_ok=True)
                with stream.extractfile(entry) as source, target.open('xb') as sink:
                    shutil.copyfileobj(source, sink)
            else:
                raise ValueError(f'Unsupported archive entry: {entry.name}')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--publication', type=Path, required=True)
    parser.add_argument('--repository', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--numerical-python', required=True)
    parser.add_argument('--variant', choices=('candidate', 'baseline'), default='candidate')
    parser.add_argument('--reuse-from', type=Path, help='Baseline only: reuse completed candidate data and initial weights')
    args = parser.parse_args()
    report = json.loads(args.publication.read_text())
    reproduction = report['reproduction']
    recorded_script = reproduction['stage_script']
    if sha(recorded_script['source'].encode()) != recorded_script['sha256']:
        raise ValueError('Recorded reconstruction source checksum differs')
    if sha(Path(__file__).read_bytes()) != recorded_script['sha256']:
        raise ValueError('Run the exact published reconstruction script')
    if args.reuse_from and args.variant != 'baseline':
        parser.error('--reuse-from requires --variant baseline')
    protocol = report['preregistration']['protocol'] if args.variant == 'candidate' else report['paired_regression']['baseline_protocol']
    if canonical(protocol['source_manifest']) != protocol['source_manifest_sha256']:
        raise ValueError('Source manifest checksum differs')
    if canonical(protocol['runner_manifest']) != protocol['runner_manifest_sha256']:
        raise ValueError('Helper manifest checksum differs')
    if canonical(protocol['recipes']) != protocol['recipe_manifest_sha256']:
        raise ValueError('Recipe checksum differs')
    commit = report['source']['archive_base_commit'] if args.variant == 'candidate' else report['paired_regression']['baseline_commit']
    args.output.mkdir()  # Exclusive, including when an earlier run aborted.
    archive(args.repository.resolve(), commit, args.output / 'source')
    if args.variant == 'candidate':
        for relative, overlay in report['source']['overlays'].items():
            target = path_under(args.output / 'source', relative)
            before = sha(target.read_bytes()) if target.exists() else None
            if before != overlay['archive_sha256']:
                raise ValueError(f'Archive base differs: {relative}')
            payload = overlay['source'].encode()
            if sha(payload) != overlay['sha256']:
                raise ValueError(f'Overlay checksum differs: {relative}')
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(payload)
    if manifest(args.output / 'source') != protocol['source_manifest']:
        raise ValueError('Staged source is not the complete frozen source')
    for relative, script in report['scripts']['frozen_helpers'].items():
        payload = script['source'].encode()
        if sha(payload) != script['sha256'] or script['sha256'] != protocol['runner_manifest'][relative]:
            raise ValueError(f'Helper checksum differs: {relative}')
        target = path_under(args.output / 'runner', relative)
        target.parent.mkdir(parents=True, exist_ok=True)
        with target.open('xb') as stream:
            stream.write(payload)
    if manifest(args.output / 'runner') != protocol['runner_manifest']:
        raise ValueError('Staged helper inventory differs')
    write_json(args.output / 'preregistered.json', protocol)
    preregistered_sha = sha((args.output / 'preregistered.json').read_bytes())
    expected_sha = report['preregistration']['sha256'] if args.variant == 'candidate' else report['paired_regression']['baseline_preregistered_sha256']
    if preregistered_sha != expected_sha:
        raise ValueError('Reconstructed preregistration bytes differ')
    write_json(args.output / 'preregistration-receipt.json', {'sha256': preregistered_sha, 'data_files_created': False, 'numerical_modules_imported': []})
    for relative in ('data', 'weights', 'checkpoints', 'predictions', 'processes'):
        (args.output / relative).mkdir()
    command = [args.numerical_python, str(args.output.resolve() / 'runner/evaluate.py')]
    commands = []
    if args.reuse_from:
        original = args.reuse_from.resolve()
        if sha((original / 'preregistered.json').read_bytes()) != report['preregistration']['sha256']:
            raise ValueError('Reuse source is not the frozen candidate protocol')
        data = json.loads((original / 'data-manifest.json').read_text())
        weights = json.loads((original / 'weight-manifest.json').read_text())
        for record in data['records']:
            for key, digest_key in [('values_path', 'file_sha256'), ('time_path', 'time_file_sha256')]:
                source = path_under(original, record[key])
                if sha(source.read_bytes()) != record[digest_key]:
                    raise ValueError(f'Reuse data checksum differs: {source}')
                shutil.copyfile(source, path_under(args.output, record[key]))
        for record in weights['records'].values():
            source = path_under(original, record['path'])
            if sha(source.read_bytes()) != record['file_sha256']:
                raise ValueError(f'Reuse weight checksum differs: {source}')
            shutil.copyfile(source, path_under(args.output, record['path']))
        data['preregistered_sha256'] = preregistered_sha
        write_json(args.output / 'data-manifest.json', data)
        weights['data_manifest_sha256'] = sha((args.output / 'data-manifest.json').read_bytes())
        write_json(args.output / 'weight-manifest.json', weights)
        for trajectory in protocol['trajectories']:
            commands.append(command + ['--stage', 'evaluate', '--directory', str(args.output.resolve()), '--trajectory', trajectory['id']])
    else:
        commands.append(command + ['--stage', 'run', '--directory', str(args.output.resolve())])
    instructions = 'After installing the pinned dependencies, with no competing benchmark or test workload, execute these commands serially. No command has been run by staging.\n\n'
    instructions += '\n'.join(shlex.join(item) for item in commands) + '\n'
    (args.output / 'RUN_IN_ORDER.txt').write_text(instructions)
    write_json(args.output / 'staging-receipt.json', {'schema': 'independent-trajectory-stdlib-staging-v1', 'variant': args.variant, 'archive_commit': commit, 'source_manifest_sha256': canonical(manifest(args.output / 'source')), 'runner_manifest_sha256': canonical(manifest(args.output / 'runner')), 'preregistered_sha256': preregistered_sha, 'numerical_modules_imported': [], 'numerical_commands_executed': [], 'commands': commands})
    print(instructions)


if __name__ == '__main__':
    main()
